import * as fs from "node:fs";
import * as path from "node:path";
import { ensureGitExclude } from "./git_exclude.js";
import { verifierTimeoutSecs } from "../tester.js";
import type {
  IntegrationReceipt,
  OperationGitState,
  OperationGitUnit,
  UnitRunResult,
  WorkUnit,
} from "./operation.js";

const GIT_TIMEOUT_MS = 300_000;

function git(cwd: string, args: string[]): string {
  return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: GIT_TIMEOUT_MS }).trim();
}

function gitResult(cwd: string, args: string[]): { ok: boolean; stdout: string; stderr: string } {
  try {
    const stdout = execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: GIT_TIMEOUT_MS });
    return { ok: true, stdout, stderr: "" };
  } catch (error: any) {
    return { ok: false, stdout: String(error?.stdout ?? ""), stderr: String(error?.stderr ?? error?.message ?? "") };
  }
}

/** Filesystem- and ref-safe name; the hash keeps two ids that sanitise the same apart. */
export function gitSlug(value: string): string {
  const clean = value.toLowerCase().replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "unit";
  return `${clean}-${createHash("sha256").update(value).digest("hex").slice(0, 8)}`;
}

export interface OperationGitPlan {
  key: string;
  repoRoot: string;
  baseRef: string;
  baseCommit: string;
  integrationBranch: string;
  integrationWorktree: string;
  baseDir: string;
}

/** Where the operation's worktrees live, and what it integrates into. Reads Git; writes nothing. */
export function planOperationGit(workspace: string, operationId: string, baseRef = "HEAD"): OperationGitPlan {
  let repoRoot: string;

const REVIEW_DIFF_MAX_BYTES = 4 * 1024 * 1024;

/**
 * The candidate a review unit judges: tracked changes against the operation's base commit (HEAD when the operation is
 * not isolated) plus untracked files, as Git renders them. A workspace that is not a Git checkout yields no diff; the
 * reviewer is told so rather than shown nothing.
 */
export function reviewCandidateDiff(workspace: string, baseCommit?: string): { base: string; diff: string } | { error: string } {
  const git = (args: string[], okExit: number[] = [0]): string => {
    try {
      return execFileSync("git", args, { cwd: workspace, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: 30_000, maxBuffer: REVIEW_DIFF_MAX_BYTES });
    } catch (err: any) {
      if (typeof err?.status === "number" && okExit.includes(err.status) && typeof err.stdout === "string") return err.stdout;
      throw err;
    }
  };
  try {
    // A base read from persisted JSON is resolved as a commit before use: a value shaped like an option is refused.
    const base = git(["rev-parse", "--verify", "--end-of-options", `${baseCommit ?? "HEAD"}^{commit}`]).trim();
    let diff = git(["diff", "--no-color", "--no-ext-diff", base, "--"]);

